import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Simplest case ---
  it.todo("empty item list → premium 5 G (only the processing fee)");

  // --- Base premiums for main items (incl. 10 % first insurance surcharge + 5 G fee) ---
  it.todo("a single plain sword → base premium 100 G");
  it.todo("a single plain amulet → base premium 60 G");
  it.todo("a single plain staff → base premium 80 G");
  it.todo("a single plain potion → base premium 40 G");

  // --- Components and building blocks ---
  it.todo("a single rune → base premium 25 G");
  it.todo("a single moonstone → base premium 25 G");
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("a cursed sword adds a 50 % risk surcharge on that item's base premium");
  it.todo("a sword with enchantment 5 adds a 30 % high-enchantment surcharge");
  it.todo("a sword with enchantment 4 gets no high-enchantment surcharge");
  it.todo("a cursed sword with enchantment 5 gets both surcharges");

  // --- Policy-wide modifiers ---
  it.todo("a customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
  it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
  it.todo("the 10 % first insurance surcharge applies to every quote's items");
  it.todo("the customer's second contract receives a 15 % follow-up discount");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword (100 G) + plain amulet (60 G) → curse surcharge is 50 G (50 % of the sword only)");

  // --- Rounding in the MHPCO's favour ---
  it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
  it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
  it.todo("intermediate amounts are kept as fractions; only the final amount is rounded");

  // --- Integration examples ---
  it.todo("newcomer (0 years) with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed sword enchantment 7 → premium 160 G");

  // --- Insurance sum and cap ---
  it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("a cursed sword (premium 165 G) → cap 2000 G (based on the unmodified insurance value)");
  it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block affects premium only)");
  it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");

  // --- Standard claim processing ---
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (value 250 G), damage 200 G → payout 100 G");

  // --- Special claim clauses ---
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
  it.todo("dragon-material sword, enchantment exactly 8, damage 1000 G → payout 400 G");

  // --- Deductible per damage event ---
  it.todo("damaged sword (500 G) and amulet (300 G) in one incident → payout 600 G (deductible per item)");
  it.todo("two insured swords, two sword damage entries → each entry gets its own deductible");

  // --- Cap exhaustion ---
  it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword policy (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");

  // --- Error cases ---
  it.todo("quote with an unknown item type (e.g. broomstick) → error");
  it.todo("claim damaging an item not covered by the policy (amulet, only sword insured) → error");
  it.todo("claim damaging an item with an unknown type → error");
  it.todo("claim with more damage entries of a type than the policy covers → error");
  it.todo("claim with a damage entry of amount -200 → error");
});

