const PROCESSING_FEE = 5;

const SWORD_PREMIUM_WITH_FIRST_INSURANCE = 110;

export type ScenarioResult = { premium: number };

export type ScenarioOutcome = { results: ScenarioResult[] };

type Scenario = { steps: { items: unknown[] }[] };

export const runScenario = (scenario: unknown): ScenarioOutcome => {
  const { steps } = scenario as Scenario;

  const results = steps.map((step) => ({
    premium: step.items.length * SWORD_PREMIUM_WITH_FIRST_INSURANCE + PROCESSING_FEE,
  }));

  return { results };
};

