const PROCESSING_FEE = 5;

const BASE_PREMIUM_BY_ITEM_TYPE = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
} as const satisfies Record<string, number>;

type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;

const BLOCK_SIZE = 3;

const BLOCK_BASE_PREMIUM = 60;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

export type ScenarioResult = { premium: number };

export type ScenarioOutcome = { results: ScenarioResult[] };

type Item = { type: InsurableItemType };

type Scenario = { steps: { items: Item[] }[] };

// Adds the surcharge as a separate term rather than scaling by 1.1, because
// `100 * 1.1` is 115.00000000000001 in binary floating point.
const withFirstInsuranceSurcharge = (amount: number): number =>
  amount + amount * FIRST_INSURANCE_SURCHARGE_RATE;

// Amounts are rounded in the MHPCO's favour: premiums (charged to the
// customer) round up.
const roundPremiumInMHPCOsFavour = (amount: number): number =>
  Math.ceil(amount);

const countByItemType = (items: Item[]): Map<InsurableItemType, number> => {
  const counts = new Map<InsurableItemType, number>();

  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }

  return counts;
};

// Exactly 3 alike components form a building block at a special base premium.
const basePremiumForAlikeItems = (
  type: InsurableItemType,
  count: number,
): number =>
  count === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];

const basePremiumOf = (items: Item[]): number =>
  [...countByItemType(items)]
    .map(([type, count]) => basePremiumForAlikeItems(type, count))
    .reduce((total, premium) => total + premium, 0);

const quotePremium = (items: Item[]): number =>
  roundPremiumInMHPCOsFavour(
    withFirstInsuranceSurcharge(basePremiumOf(items)) + PROCESSING_FEE,
  );

export const runScenario = (scenario: unknown): ScenarioOutcome => {
  const { steps } = scenario as Scenario;

  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));

  return { results };
};

