import { describe, it, expect } from "vitest";
import { spawn } from "node:child_process";
import { fileURLToPath } from "node:url";

const CLI = fileURLToPath(new URL("./cli.ts", import.meta.url));

type CliRun = { stdout: string; stderr: string; code: number };

// Spawns the real CLI so the tests exercise the actual stdin/stdout contract.
const runCli = (input: string): Promise<CliRun> =>
  new Promise((resolve, reject) => {
    const child = spawn("npx", ["tsx", CLI], {
      stdio: ["pipe", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";

    child.stdout.on("data", (chunk) => (stdout += chunk));
    child.stderr.on("data", (chunk) => (stderr += chunk));
    child.on("error", reject);
    child.on("close", (code) => resolve({ stdout, stderr, code: code ?? 0 }));

    child.stdin.write(input);
    child.stdin.end();
  });

describe("claim-office CLI", () => {
  it(
    "reads a scenario from stdin and writes {results: [...]} to stdout",
    async () => {
      const scenario = {
        customer: { yearsWithMHPCO: 5 },
        steps: [
          {
            op: "quote",
            items: [
              {
                type: "amulet",
                material: "silver",
                enchantment: 2,
                cursed: false,
              },
            ],
          },
        ],
      };

      const { stdout, code } = await runCli(JSON.stringify(scenario));

      expect(code).toBe(0);
      expect(JSON.parse(stdout)).toEqual({ results: [{ premium: 59 }] });
    },
    30000,
  );

  it.todo("writes one result per step, in the same order as the input steps");
  it.todo("quote results contain a premium integer; claim results contain payout and remainingCap");
  it.todo("exits with a non-zero status and writes to stderr for an unknown item type, with no results on stdout");
  it.todo("exits with a non-zero status and writes to stderr for a damage entry not covered by the policy");
  it.todo("exits with a non-zero status and writes to stderr for a negative damage amount");
  it.todo("exits with a non-zero status and writes to stderr for stdin that is not a valid scenario");
});

